140	fn recorded_resolution_for(
141	    context: &mut NifContext,
142	    activity_id: &ActivityId,
143	) -> Result<Option<Resolution>, EngineError> {
144	    let ordinal = activity_id.sequence_position();
145	    let input =
146	        Payload::from_json(&serde_json::Value::Null).map_err(|error| EngineError::Runtime {
147	            reason: format!("await_activity_result replay input: {error}"),
148	        })?;
149	    match context
150	        .resolve_command(Command::RunActivity {
151	            key: CorrelationKey::Activity(ordinal),
152	            activity_type: "await_activity_result".to_owned(),
153	            input,
154	        })
155	        .map_err(|error| EngineError::Runtime {
156	            reason: error.error_reason(),
157	        })? {
158	        ResolveOutcome::Recorded(resolution) => Ok(Some(resolution)),
159	        ResolveOutcome::ResumeLive => Ok(None),
160	    }
161	}
