163	fn recorded_step(resolution: Resolution) -> ActivityAwaitStep {
164	    match resolution {
165	        Resolution::ActivityCompleted(payload) => {
166	            ActivityAwaitStep::Completed(payload.bytes().to_vec())
167	        }
168	        Resolution::ActivityFailedTerminal(error) => ActivityAwaitStep::Failed(error.message),
169	        other => ActivityAwaitStep::Failed(format!(
170	            "await_activity_result: recorded non-activity resolution {other:?}"
171	        )),
172	    }
173	}
