175	fn take_runtime_completion(
176	    context: &NifContext,
177	    runtime: &crate::RuntimeHandle,
178	    activity_id: ActivityId,
179	) -> Result<Option<ActivityAwaitStep>, EngineError> {
180	    let ordinal = activity_id.sequence_position();
181	    if let Some((payload, attempt)) = runtime.take_activity_result(context.pid(), ordinal)? {
182	        // NOI-0/#197: the completion task retains the attempt that produced the
183	        // delivered outcome (a retry loop can move it past the first delivery);
184	        // paths that never retry (outbox re-delivery, in-VM) retain nothing and
185	        // resolve to the first delivery exactly as before.
186	        let attempt = attempt.unwrap_or(FIRST_DELIVERY_ATTEMPT);
187	        context
188	            .record_activity_completed(chrono::Utc::now(), activity_id, payload.clone(), attempt)
189	            .map_err(|error| EngineError::Runtime {
190	                reason: error.error_reason(),
191	            })?;
192	        return Ok(Some(ActivityAwaitStep::Completed(payload.bytes().to_vec())));
193	    }
194	    if let Some((error, attempt)) = runtime.take_activity_error(context.pid(), ordinal)? {
195	        // #197: an exhausted retry budget fails the workflow with the LAST
196	        // reason verbatim and the final attempt count on the recorded
197	        // terminal `ActivityFailed`.
198	        let attempt = attempt.unwrap_or(FIRST_DELIVERY_ATTEMPT);
199	        context
200	            .record_activity_failed(
201	                chrono::Utc::now(),
202	                activity_id,
203	                activity_error(error.message.clone()),
204	                attempt,
205	            )
206	            .map_err(|record_error| EngineError::Runtime {
207	                reason: record_error.error_reason(),
208	            })?;
209	        return Ok(Some(ActivityAwaitStep::Failed(error.message)));

