15	/// One activity this run dispatched and that has recorded no terminal event.
16	#[derive(Clone, Debug, PartialEq, Eq)]
17	pub(crate) struct CurrentStep {
18	    /// The activity ordinal within the run.
19	    pub(crate) activity_id: u64,
20	    /// The activity type, from the run's own `ActivityScheduled`.
21	    pub(crate) activity_type: String,
22	    /// The attempt that is in flight.
23	    pub(crate) attempt: u32,
24	    /// The task queue the dispatch was recorded against.
25	    pub(crate) task_queue: Option<String>,
26	    /// The node affinity recorded on the dispatch, if any.
27	    pub(crate) node: Option<String>,
28	    /// When the ENGINE recorded the dispatch — not when a worker took it, which
29	    /// may be a thing that never happened. `unserved` is what distinguishes the
30	    /// two.
31	    pub(crate) dispatched_at: String,
32	}
33	
34	/// Fold a run's own segment into its current step.
35	///
36	/// "Current" is the LAST activity the run dispatched that no later event
37	/// terminates. Terminals are matched on `(activity_id, attempt)`, not on
38	/// `activity_id` alone: a retry is a new attempt, and an earlier attempt's
39	/// failure must not be read as terminating the attempt now in flight.
40	pub(crate) fn current_step(segment: &[Event]) -> Option<CurrentStep> {
41	    let mut scheduled: BTreeMap<u64, (String, Option<String>, Option<String>)> = BTreeMap::new();
42	    let mut live: BTreeMap<(u64, u32), (usize, String)> = BTreeMap::new();
43	    for (position, event) in segment.iter().enumerate() {
44	        match event {
45	            Event::ActivityScheduled {
46	                activity_id,
47	                activity_type,
48	                task_queue,
49	                node,
50	                ..
51	            } => {
52	                scheduled.insert(
53	                    activity_id.sequence_position(),
54	                    (
55	                        activity_type.clone(),
56	                        Some(task_queue.clone()),
57	                        node.clone(),
58	                    ),
59	                );
60	            }
61	            Event::ActivityStarted {
62	                envelope,
63	                activity_id,
64	                attempt,
65	            } => {
66	                live.insert(
67	                    (activity_id.sequence_position(), *attempt),
68	                    (position, envelope.recorded_at.to_rfc3339()),
69	                );
70	            }
71	            Event::ActivityCompleted {
72	                activity_id,
73	                attempt,
74	                ..
75	            }
76	            | Event::ActivityFailed {
77	                activity_id,
78	                attempt,
79	                ..
80	            }
81	            | Event::ActivityCancelled {
82	                activity_id,
83	                attempt,
84	                ..
85	            } => {
86	                drop(live.remove(&(activity_id.sequence_position(), *attempt)));
87	            }
88	            _ => {}
89	        }
90	    }
91	    let ((activity_id, attempt), (_, dispatched_at)) = live
92	        .into_iter()
93	        .max_by_key(|(_, (position, _))| *position)?;
94	    let (activity_type, task_queue, node) = scheduled
95	        .get(&activity_id)
96	        .cloned()
97	        .unwrap_or_else(|| (String::from("<unrecorded>"), None, None));
98	    Some(CurrentStep {
99	        activity_id,
100	        activity_type,
101	        attempt,
102	        task_queue,
103	        node,
104	        dispatched_at,
105	    })
106	}
107	
108	/// Every retained transcript stream of this run, each as a complete
109	/// `read_transcript` handle.
110	///
111	/// The enumeration is run-scoped by the storage key itself: the run sits inside
112	/// the `O`-region scan prefix, so a sibling generation's streams are excluded
113	/// by the key range, not by a droppable predicate here.
114	async fn transcript_handles(
115	    state: &ServerState,
116	    view: &RunView,
117	) -> Result<Vec<Value>, ToolFailure> {
118	    let summaries = state
119	        .transcript_publisher()
120	        .list_streams(&view.workflow_id, &view.run_id)
121	        .await
122	        .map_err(|error| tool_failure(&crate::ServerError::from(error).to_wire_error()))?;
123	    let mut handles = Vec::new();
124	    for summary in summaries {
125	        handles.push(json!({
126	            "workflow_id": view.workflow_id.to_string(),
127	            "run_id": view.run_id.to_string(),
128	            "activity_id": summary.key.activity_id.sequence_position(),
129	            "attempt": summary.key.attempt,
130	            "head_seq": summary.head,
131	        }));
132	    }
133	    Ok(handles)
134	}
