136	/// Run `describe_run`.
137	///
138	/// # Errors
139	///
140	/// [`ToolFailure`] when the arguments are malformed, the caller does not hold
141	/// the namespace, or the workflow/run does not exist.
142	pub(crate) async fn describe_run(
143	    state: &ServerState,
144	    caller: &CallerIdentity,
145	    call: &ToolCall,
146	) -> Result<ToolOutcome, ToolFailure> {
147	    let view = RunView::read(state, caller, call).await?;
148	    let step = current_step(view.run_segment());
149	    let unserved = ActivityReachability {
150	        registry: state.worker_registry(),
151	        declarations: state.queue_declarations(),
152	        state: state.queue_service_state(),
153	    }
154	    .unserved(&view.namespace, &view.workflow_id, &view.history)
155	    .map_err(|error| tool_failure(&error.to_wire_error()))?;
156	    let transcripts = transcript_handles(state, &view).await?;
157	    let unserved = serde_json::to_value(&unserved).map_err(|error| {
158	        ToolFailure::new(
159	            format!("the unserved-activity verdict could not be encoded: {error}"),
160	            json!({ "code": "backend" }),
161	        )
162	    })?;
163	
164	    let summary_line = format!(
165	        "{} run {} is {:?}{}",
166	        view.summary.workflow_type,
167	        view.run_id,
168	        view.summary.status,
169	        step.as_ref().map_or_else(String::new, |step| format!(
170	            "; current step is activity {} ({}) attempt {}",
171	            step.activity_id, step.activity_type, step.attempt
172	        ))
173	    );
174	
175	    Ok(ToolOutcome {
176	        structured: json!({
177	            "namespace": view.namespace,
178	            "workflow_id": view.workflow_id.to_string(),
179	            "run_id": view.run_id.to_string(),
180	            "workflow_type": view.summary.workflow_type,
181	            // #211: the operator-facing label, so an agent that SET a display
182	            // name can read it back here rather than only through `list_runs`.
183	            // Per WORKFLOW, not per run — the recorded attribute carries no run
184	            // id and the projection folds the whole history — which is why it
185	            // sits beside the workflow's own fields and not inside
186	            // `current_step`.
187	            "display_name": view.summary.display_name,
188	            "status": view.summary.status,
189	            "started_at": view.summary.started_at.to_rfc3339(),
190	            "ended_at": view.summary.ended_at.map(|at| at.to_rfc3339()),
191	            "failed_step": view.summary.failed_step,
192	            "failure_reason": view.summary.failure_reason,
193	            "history_head_seq": view.history_head_seq(),
