14	/// The describe read's full result: the wire response every transport returns,
15	/// plus the two inputs a transport may need to project further.
16	///
17	/// The scoped `namespace` and the decoded `history` are handed back rather than
18	/// dropped because the HTTP surface projects an unserved-activity verdict over
19	/// them ([`crate::worker::ActivityReachability`]). Recomputing either at the
20	/// transport would mean a second namespace scope and a second `read_history` for
21	/// one request, and — worse — a second answer that could disagree with the one
22	/// the summary was built from.
23	#[derive(Debug)]
24	pub struct DescribeOutcome {
25	    /// Wire response: the encoded summary and (optionally) the encoded history.
26	    pub response: ProtoDescribeWorkflowResponse,
27	    /// The namespace the caller was scoped to.
28	    pub namespace: String,
29	    /// The workflow the read resolved to.
30	    pub workflow_id: aion_core::WorkflowId,
31	    /// The run's decoded history, read in full regardless of `include_history`.
32	    pub history: Vec<Event>,
33	}
34	
35	/// Handles a decoded describe-workflow request.
36	///
37	/// # Errors
38	///
39	/// Returns a stable [`WireError`] when IDs are missing or malformed, namespace scoping fails, store
40	/// history reading fails, the workflow has no summary, or response envelopes cannot be encoded.
41	pub async fn describe(
42	    guard: &NamespaceGuard,
43	    caller: &CallerIdentity,
44	    request: ProtoDescribeWorkflowRequest,
45	) -> Result<DescribeOutcome, WireError> {
46	    let workflow_id = required_workflow_id(request.workflow_id.clone())?;
47	    let target = WorkflowTarget::workflow(&workflow_id);
48	    let scoped = guard
49	        .scope(caller, &NamespaceOperation::describe(&request, target))
50	        .await
51	        .map_err(|error| error.to_wire_error())?;
52	    let engine = scoped.engine().map_err(|error| error.to_wire_error())?;
53	    resolve_run_id(engine.as_ref(), &workflow_id, request.run_id.clone()).await?;
54	
55	    let history = engine
56	        .store()
57	        .read_history(&workflow_id)
58	        .await
59	        .map_err(|error| ServerError::from(error).to_wire_error())?;
60	    let summary = WorkflowSummary::from_history(&history)
61	        .ok_or_else(|| workflow_not_found_error(&workflow_id))?;
62	    let namespace = scoped.namespace().to_owned();
63	    let summary = encode_workflow_summary(namespace.clone(), None, &summary)?;
64	    let encoded_history = encode_history(request.include_history, &namespace, &history)?;
65	
66	    Ok(DescribeOutcome {
67	        response: ProtoDescribeWorkflowResponse {
68	            summary: Some(summary),
69	            history: encoded_history,
70	        },
71	        namespace,
72	        workflow_id,
73	        history,
74	    })
75	}
