2	
3	import { ApiError } from './api-error';
4	
5	/** Optional fields use the server defaults when omitted. */
6	export type HistoryWindowRequest = {
7	  fromSeq?: number;
8	  limit?: number;
9	  /** Zero disables payload-byte elision. */
10	  payloadLimitBytes?: number;
11	};
12	
13	export type HistoryWindow = {
14	  events: Event[];
15	  nextFromSeq: number | null;
16	  headSeq: number;
17	};
18	
19	export function decodeHistoryWindow(value: unknown): HistoryWindow {
20	  if (!isRecord(value) || !Array.isArray(value.events)) {
21	    throw contractError('workflows/history response missing an events array');
22	  }
23	
24	  const nextFromSeq = value.next_from_seq;
25	  if (nextFromSeq !== null && !isSequence(nextFromSeq)) {
26	    throw contractError('workflows/history response has an invalid next_from_seq');
27	  }
28	  if (!isSequence(value.head_seq)) {
29	    throw contractError('workflows/history response has an invalid head_seq');
30	  }
31	  if (!value.events.every(isEvent)) {
32	    throw contractError('workflows/history response contains an invalid event');
33	  }
34	
35	  return {
36	    events: value.events,
37	    nextFromSeq,
38	    headSeq: value.head_seq,
39	  };
40	}
41	
42	export function decodeEventResponse(value: unknown): Event {
43	  if (!isRecord(value) || !isEvent(value.event)) {
44	    throw contractError('workflows/event response missing a valid event');
45	  }
46	  return value.event;
47	}
48	
49	function isEvent(value: unknown): value is Event {
50	  if (!isRecord(value) || typeof value.type !== 'string' || !isRecord(value.data)) {
51	    return false;
52	  }
53	  const envelope = value.data.envelope;
54	  return (
55	    isRecord(envelope) &&
56	    isSequence(envelope.seq) &&
57	    typeof envelope.recorded_at === 'string' &&
58	    typeof envelope.workflow_id === 'string'
59	  );
60	}
61	
62	function isSequence(value: unknown): value is number {
63	  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
64	}
65	
66	function isRecord(value: unknown): value is Record<string, unknown> {
67	  return typeof value === 'object' && value !== null && !Array.isArray(value);
68	}
69	
70	function contractError(message: string): ApiError {
71	  return new ApiError(200, message);
72	}

