56	/// `POST /workflows/history`.
57	pub(crate) async fn fetch_history(
58	    State(state): State<ServerState>,
59	    HttpCaller(caller): HttpCaller,
60	    Json(request): Json<HistoryFetchRequest>,
61	) -> Result<Json<HistoryFetchResponse>, HttpWireError> {
62	    let workflow_id = parse_workflow_id(&request.workflow_id)?;
63	    let engine = scoped_engine(
64	        &state,
65	        &caller,
66	        &request.namespace,
67	        &request.workflow_id,
68	        &workflow_id,
69	    )
70	    .await?;
71	    let from_seq = request.from_seq.map_or(0, |seq| seq);
72	    let limit = request
73	        .limit
74	        .map_or(DEFAULT_HISTORY_LIMIT, |limit| limit)
75	        .clamp(1, MAX_WINDOW_LIMIT) as usize;
76	    let payload_limit = request
77	        .payload_limit_bytes
78	        .map_or(DEFAULT_PAYLOAD_LIMIT_BYTES, |limit| limit);
79	    let ranged = engine
80	        .store()
81	        .read_history_from(&workflow_id, from_seq)
82	        .await
83	        .map_err(store_error)?;
84	
85	    // A ranged read beyond the head cannot report the head. Fall back to the
86	    // complete snapshot only for that empty-tail edge, and project the range
87	    // from the same snapshot so a concurrent append cannot create a gap.
88	    let (mut tail, head_seq) = if ranged.is_empty() {
89	        let mut history = engine
90	            .store()
91	            .read_history(&workflow_id)
92	            .await
93	            .map_err(store_error)?;
94	        let head_seq = history.last().map_or(0, Event::seq);
95	        history.retain(|event| event.seq() >= from_seq);
96	        (history, head_seq)
97	    } else {
98	        let head_seq = ranged.last().map_or(0, Event::seq);
99	        (ranged, head_seq)
100	    };
101	
102	    let next_from_seq = tail.get(limit).map(Event::seq);
103	    tail.truncate(limit);
104	    let events = tail
105	        .into_iter()
106	        .map(|event| project_event(event, payload_limit))
107	        .collect::<Result<Vec<_>, _>>()?;
108	
109	    Ok(Json(HistoryFetchResponse {
110	        events,
111	        next_from_seq,
112	        head_seq,
113	    }))
114	}
