1	//! Replay driver to the resume point.
2	//!
3	//! Replay is an orchestration layer above [`Resolver`]. AE owns the workflow process and feeds the
4	//! commands it emits into this driver. While history satisfies commands, the driver returns recorded
5	//! resolutions and advances the deterministic timestamp. The first command history cannot satisfy is
6	//! reported as the resume-live point for AE's AD-007 handoff.
7	
8	use aion_core::{Event, Payload, RunId, WorkflowError, WorkflowId};
9	use chrono::{DateTime, Utc};
10	
11	use crate::durability::{
12	    Command, DeterminismContext, DurabilityError, HistoryCursor, LiveExecutor, NonDeterminismError,
13	    Recorder, Resolution, ResolvedCommand, Resolver,
14	};
15	
16	/// Stateful replay driver for one workflow history.
17	pub struct Replay {
18	    workflow_id: WorkflowId,
19	    resolver: Resolver,
20	    determinism: DeterminismContext,
21	    terminal: Option<TerminalRecord>,
22	}
23	
24	#[derive(Clone, Debug, PartialEq, Eq)]
25	struct TerminalRecord {
26	    seq: u64,
27	    terminal: ReplayTerminal,
28	}
29	
30	impl Replay {
31	    /// Assembles replay state from a workflow id, run id, and ordered recorded history.
32	    ///
33	    /// # Errors
34	    ///
35	    /// Returns [`DurabilityError::HistoryShape`] if the history is unordered or lacks a
36	    /// `WorkflowStarted` event for the requested workflow.
37	    pub fn new(
38	        workflow_id: &WorkflowId,
39	        run_id: &RunId,
40	        history: Vec<Event>,
41	    ) -> Result<Self, DurabilityError> {
42	        let history = crate::durability::current_run_segment(history, run_id)?;
43	        let started_at = workflow_started_at(workflow_id, &history)?;
44	        let terminal = terminal_from_history(workflow_id, &history);
45	        let cursor = HistoryCursor::new(history)?;
46	        let resolver = Resolver::new(workflow_id.clone(), cursor);
47	        let determinism = DeterminismContext::new(started_at);
48	
49	        Ok(Self {
50	            workflow_id: workflow_id.clone(),
51	            resolver,
52	            determinism,
53	            terminal,
54	        })
55	    }
56	
57	    /// Assembles replay state while accepting the AD-007 handoff collaborators.
58	    ///
59	    /// Replay keeps live execution out of the recorded path; these handles are accepted so AE can
60	    /// construct replay and retain the same collaborators for the first [`ReplayStep::ResumeLive`].
61	    ///
62	    /// # Errors
63	    ///
64	    /// Returns the same history-shape errors as [`Self::new`].
65	    pub fn with_handoff(
66	        workflow_id: &WorkflowId,
67	        run_id: &RunId,
68	        history: Vec<Event>,
69	        recorder: &Recorder,
70	        executor: &dyn LiveExecutor,
71	    ) -> Result<Self, DurabilityError> {
72	        let _ = recorder.workflow_id();
73	        let _ = executor;
74	        Self::new(workflow_id, run_id, history)
75	    }
76	
77	    /// Returns the deterministic workflow-visible timestamp currently applied by replay.
78	    #[must_use]
79	    pub const fn now(&self) -> DateTime<Utc> {
80	        self.determinism.now()
81	    }
82	
83	    /// Resolves the next engine-supplied workflow command against recorded history.
84	    ///
85	    /// # Errors
86	    ///
87	    /// Returns resolver errors, including typed non-determinism violations at the mismatch point.
88	    pub fn step(&mut self, command: &Command) -> Result<ReplayStep, DurabilityError> {
89	        match self.resolver.resolve_with_consumed(command.clone())? {
90	            ResolvedCommand::Recorded {
91	                resolution,
92	                recorded_at,
93	            } => {
94	                self.determinism.advance_to_recorded_at(recorded_at);
95	                Ok(ReplayStep::Recorded(resolution))
96	            }
97	            ResolvedCommand::ResumeLive { recorded_at } => {
98	                if let Some(recorded_at) = recorded_at {
99	                    self.determinism.advance_to_recorded_at(recorded_at);
100	                }
101	                self.resume_or_terminal(command)
102	            }
103	        }
104	    }
105	
106	    /// Drives replay over an iterator of commands until a resume-live or terminal point appears.
107	    ///
108	    /// Recorded resolutions are included in the returned outcome so AE can return them to the
109	    /// workflow process in order before acting on the handoff.
110	    ///
111	    /// # Errors
112	    ///
113	    /// Returns resolver errors, including typed non-determinism violations at the mismatch point.
114	    pub fn drive<I>(&mut self, commands: I) -> Result<ReplayOutcome, DurabilityError>
115	    where
116	        I: IntoIterator<Item = Command>,
117	    {
118	        let mut recorded = Vec::new();
119	        for (command_index, command) in commands.into_iter().enumerate() {
120	            match self.step(&command)? {
121	                ReplayStep::Recorded(resolution) => recorded.push(resolution),
122	                ReplayStep::ResumeLive => {
123	                    return Ok(ReplayOutcome::ResumeLive {
124	                        command_index,
125	                        command,
126	                        recorded,
127	                    });
128	                }
129	                ReplayStep::Terminal(terminal) => {
130	                    return Ok(ReplayOutcome::Terminal { terminal, recorded });
131	                }
132	            }
133	        }
134	
135	        if let Some(terminal) = self.terminal.clone() {
136	            Ok(ReplayOutcome::Terminal {
137	                terminal: terminal.terminal,
138	                recorded,
139	            })
140	        } else {
141	            Ok(ReplayOutcome::AwaitingCommand { recorded })
142	        }
143	    }
144	
145	    fn resume_or_terminal(&self, command: &Command) -> Result<ReplayStep, DurabilityError> {
146	        let Some(terminal) = &self.terminal else {
147	            return Ok(ReplayStep::ResumeLive);
148	        };
149	
150	        if let (Command::CompleteWorkflow { result }, ReplayTerminal::Completed(recorded_result)) =
151	            (command, &terminal.terminal)
152	        {
153	            if result == recorded_result {
154	                return Ok(ReplayStep::Terminal(terminal.terminal.clone()));
155	            }

